package org.freecad.mobilelab;
import android.app.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.text.InputType;import java.util.*;
/** XY drawing/pole editing; weights and Z remain explicit. Apply commits one CAD transaction. */
final class SketchCanvas {
 interface Result{void accept(String kind,double[] points,boolean closed);}
 static void show(Activity a,Result r){new Editor(a,r,null).show();}
 static void edit(Activity a,double[] data,Result r){new Editor(a,r,data).show();}
 private static final String[] CURVE_KINDS={"Polyline","Interpolated curve","NURBS curve"};
 static final class Editor {
  final Activity a;final Result result;final ArrayList<double[]> points=new ArrayList<>();final ArrayList<double[][]> history=new ArrayList<>();final boolean editing;Dialog dialog;CanvasView canvas;Spinner kind;EditText grid;CheckBox closed,snap,ortho;TextView status;int selected=-1;
  Editor(Activity a,Result r,double[] data){this.a=a;result=r;editing=data!=null;if(data!=null)for(int i=0;i<data.length;i+=4)points.add(Arrays.copyOfRange(data,i,i+4));}int dp(int x){return Math.round(x*a.getResources().getDisplayMetrics().density);}
  void remember(){double[][] copy=new double[points.size()][];for(int i=0;i<copy.length;i++)copy[i]=points.get(i).clone();history.add(copy);if(history.size()>24)history.remove(0);}
  void undo(){if(history.isEmpty())return;double[][] old=history.remove(history.size()-1);points.clear();for(double[] p:old)points.add(p.clone());selected=Math.min(selected,points.size()-1);}
  void show(){dialog=new Dialog(a);LinearLayout root=new LinearLayout(a);root.setOrientation(1);root.setBackgroundColor(0xff111820);root.setPadding(dp(8),dp(8),dp(8),dp(8));TextView title=new TextView(a);title.setTextColor(0xffedf3f8);L10n.setText(title,editing?"XY poles · drag points · Z / weight via Point":"XY sketch · tap to add, drag to edit · pinch / two fingers pan");root.addView(title);kind=new Spinner(a);kind.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,L10n.labels(a,CURVE_KINDS)));if(editing){kind.setSelection(2);kind.setEnabled(false);}root.addView(kind);LinearLayout settings=new LinearLayout(a);grid=new EditText(a);grid.setTextColor(0xffedf3f8);L10n.setHint(grid,"Grid mm");grid.setText("1");grid.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);settings.addView(grid,new LinearLayout.LayoutParams(dp(65),dp(44)));closed=new CheckBox(a);L10n.setText(closed,"Closed");closed.setEnabled(!editing);settings.addView(closed);snap=new CheckBox(a);L10n.setText(snap,"Snap");snap.setChecked(true);settings.addView(snap);ortho=new CheckBox(a);L10n.setText(ortho,"Ortho");settings.addView(ortho);for(CheckBox c:new CheckBox[]{closed,snap,ortho})c.setTextColor(0xffedf3f8);root.addView(settings);canvas=new CanvasView();root.addView(canvas,new LinearLayout.LayoutParams(-1,0,1));status=new TextView(a);status.setTextColor(0xff99aabe);L10n.setText(status,"Snap: poles, control-segment midpoints/intersections and grid. NURBS preview is rational; interpolation uses a through-point guide until Apply.");root.addView(status);LinearLayout bar=new LinearLayout(a);for(String name:new String[]{"Undo","Point","Clear","Apply","Cancel"}){Button b=new Button(a);L10n.setText(b,name);b.setTextSize(10);bar.addView(b,new LinearLayout.LayoutParams(0,dp(50),1));b.setOnClickListener(v->{if(name.equals("Undo"))undo();if(name.equals("Point"))point();if(name.equals("Clear")){remember();points.clear();selected=-1;}if(name.equals("Cancel"))dialog.dismiss();if(name.equals("Apply"))apply();canvas.invalidate();});}root.addView(bar);dialog.setContentView(root);dialog.show();dialog.getWindow().setLayout(-1,-1);canvas.post(()->{if(editing&&!points.isEmpty()){double minX=1e100,minY=minX,maxX=-minX,maxY=-minX;for(double[] p:points){minX=Math.min(minX,p[0]);minY=Math.min(minY,p[1]);maxX=Math.max(maxX,p[0]);maxY=Math.max(maxY,p[1]);}canvas.zoom=(float)Math.max(dp(1),Math.min(dp(100),Math.min(canvas.getWidth()*.7/Math.max(1,maxX-minX),canvas.getHeight()*.7/Math.max(1,maxY-minY))));canvas.panX=(float)(-(minX+maxX)/2*canvas.zoom);canvas.panY=(float)((minY+maxY)/2*canvas.zoom);canvas.invalidate();}});kind.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int position,long id){canvas.invalidate();}});closed.setOnCheckedChangeListener((b,on)->canvas.invalidate());}
  void point(){if(selected<0||selected>=points.size()){L10n.setText(status,"Tap a pole first");return;}final int index=selected;double[] p=points.get(index);LinearLayout panel=new LinearLayout(a);panel.setOrientation(1);EditText[] fields=new EditText[4];for(int i=0;i<4;i++){EditText e=new EditText(a);L10n.setHint(e,new String[]{"X mm","Y mm","Z mm","Weight"}[i]);e.setText(String.valueOf(p[i]));e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);panel.addView(e);fields[i]=e;}AlertDialog form=new UiDialog(a).setTitle("Pole "+(index+1)+" · XYZ / weight").setView(panel).setNegativeButton("Cancel",null).setPositiveButton("Apply",null).create();form.setOnShowListener(v->form.getButton(-1).setOnClickListener(b->{try{double[] q=new double[4];for(int i=0;i<4;i++){q[i]=Double.parseDouble(fields[i].getText().toString().replace(',','.'));if(!Double.isFinite(q[i])||(i<3&&Math.abs(q[i])>10000)||(i==3&&(q[i]<.001||q[i]>1000)))throw new IllegalArgumentException("XYZ +/-10,000 mm; weight .001 to 1000");}remember();points.set(index,q);form.dismiss();canvas.invalidate();}catch(Exception e){Toast.makeText(a,L10n.text(a,e.getMessage()),Toast.LENGTH_SHORT).show();}}));form.show();}
  void apply(){try{if(points.size()<2)throw new IllegalArgumentException("Add at least two points");String type=CURVE_KINDS[kind.getSelectedItemPosition()];if(type.equals("NURBS curve")&&closed.isChecked())throw new IllegalArgumentException("Closed curve requires Polyline / Interpolated curve");if(closed.isChecked()&&points.size()<3)throw new IllegalArgumentException("Closed curve needs three points");double[] data=new double[points.size()*4];for(int i=0;i<points.size();i++)System.arraycopy(points.get(i),0,data,i*4,4);dialog.dismiss();result.accept(type,data,closed.isChecked());}catch(Exception e){L10n.setText(status,e.getMessage());}}
  final class CanvasView extends View {
   final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);final ScaleGestureDetector scaling;float zoom=dp(12),panX,panY,lastX,lastY,downX,downY;int previous,drag=-1;boolean multi,moved;
   CanvasView(){super(a);scaling=new ScaleGestureDetector(a,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){zoom=Math.max(dp(1),Math.min(dp(100),zoom*d.getScaleFactor()));invalidate();return true;}});}
   float sx(double x){return getWidth()/2f+panX+(float)x*zoom;}float sy(double y){return getHeight()/2f+panY-(float)y*zoom;}
   protected void onDraw(Canvas c){super.onDraw(c);float ox=sx(0),oy=sy(0);double step=1;try{step=Double.parseDouble(grid.getText().toString());}catch(Exception ignored){}if(!Double.isFinite(step)||step<=0||step>100)step=1;float spacing=(float)(step*zoom);while(spacing<dp(10))spacing*=10;paint.setColor(0xff23303d);paint.setStrokeWidth(1);for(float x=ox%spacing;x<getWidth();x+=spacing)c.drawLine(x,0,x,getHeight(),paint);for(float y=oy%spacing;y<getHeight();y+=spacing)c.drawLine(0,y,getWidth(),y,paint);paint.setColor(0xff7d4850);c.drawLine(0,oy,getWidth(),oy,paint);paint.setColor(0xff44734f);c.drawLine(ox,0,ox,getHeight(),paint);paint.setStrokeWidth(dp(1));paint.setColor(0xff567b80);for(int i=1;i<points.size();i++)c.drawLine(sx(points.get(i-1)[0]),sy(points.get(i-1)[1]),sx(points.get(i)[0]),sy(points.get(i)[1]),paint);if(closed.isChecked()&&points.size()>2)c.drawLine(sx(points.get(0)[0]),sy(points.get(0)[1]),sx(points.get(points.size()-1)[0]),sy(points.get(points.size()-1)[1]),paint);if(kind.getSelectedItemPosition()==2&&points.size()>=2){paint.setColor(0xff59dfc4);paint.setStrokeWidth(dp(2));double[] prev=SketchMath.nurbs(points,0);for(int k=1;k<=160;k++){double[] next=SketchMath.nurbs(points,k/160.);c.drawLine(sx(prev[0]),sy(prev[1]),sx(next[0]),sy(next[1]),paint);prev=next;}}for(int i=0;i<points.size();i++){double[] p=points.get(i);paint.setColor(i==selected?0xffffc66d:0xff59dfc4);c.drawCircle(sx(p[0]),sy(p[1]),dp(i==selected?6:4),paint);paint.setTextSize(dp(11));c.drawText(String.valueOf(i+1),sx(p[0])+dp(5),sy(p[1])-dp(5),paint);}}
   void update(float x,float y,int index){double gridSize=Double.parseDouble(grid.getText().toString().replace(',','.'));SketchMath.Snap p=SketchMath.snap((x-getWidth()/2f-panX)/zoom,-(y-getHeight()/2f-panY)/zoom,gridSize,dp(10)/zoom,points,index,snap.isChecked(),ortho.isChecked());if(index>=0){double[] old=points.get(index);points.set(index,new double[]{p.x,p.y,old[2],old[3]});}else{if(points.size()>=64)throw new IllegalArgumentException("Maximum 64 points");remember();points.add(new double[]{p.x,p.y,0,1});selected=points.size()-1;}L10n.setText(status,String.format(Locale.US,L10n.text(a,"%s · X %.3f, Y %.3f mm"),p.kind,p.x,p.y));}
   public boolean onTouchEvent(MotionEvent event){scaling.onTouchEvent(event);int count=event.getPointerCount();float x=event.getX(),y=event.getY();int action=event.getActionMasked();if(count>1){x=(x+event.getX(1))/2;y=(y+event.getY(1))/2;multi=true;drag=-1;}if(action==MotionEvent.ACTION_DOWN){downX=x;downY=y;multi=moved=false;drag=-1;double nearest=dp(12);for(int i=0;i<points.size();i++){double[] p=points.get(i);double distance=Math.hypot(sx(p[0])-x,sy(p[1])-y);if(distance<nearest){nearest=distance;drag=i;}}if(drag>=0){selected=drag;remember();}}if(action==MotionEvent.ACTION_MOVE&&count>1&&previous>1){panX+=x-lastX;panY+=y-lastY;}if(action==MotionEvent.ACTION_MOVE&&count==1&&drag>=0&&!multi){try{update(x,y,drag);moved=true;}catch(Exception e){L10n.setText(status,e.getMessage());}}if(action==MotionEvent.ACTION_UP&&!multi&&drag<0&&Math.hypot(x-downX,y-downY)<dp(10))try{update(x,y,-1);}catch(Exception e){L10n.setText(status,e.getMessage());}if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_CANCEL)drag=-1;lastX=x;lastY=y;previous=count;invalidate();return true;}
  }
 }
}
